class BitEvidenceEncodingTest(unittest.TestCase):
    def _blob(self, rounds=2):
        return verifier().bits(
            RecordingProver(KEY), CONTEXT, OPENING, rounds=rounds
        )

    def test_is_frozen(self):
        record = BitEvidence.from_bytes(self._blob())
        with self.assertRaises(AttributeError):
            record.limit = 1.0

    def test_round_trip(self):
        blob = self._blob()
        self.assertEqual(BitEvidence.from_bytes(blob).to_bytes(), blob)

    def test_rejects_non_bytes(self):
        for bad in (self._blob().decode(), bytearray(self._blob()), None, 42, []):
            with self.assertRaises(ValueError):
                BitEvidence.from_bytes(bad)

    def test_rejects_malformed_json(self):
        with self.assertRaises(ValueError):
            BitEvidence.from_bytes(b"{not json")

    def test_rejects_wrong_array_shape(self):
        blob = self._blob()
        array = session(blob)
        for mutate in (
            lambda a: a.pop(),
            lambda a: a.append(1),
            lambda a: a.__setitem__(0, 2),
        ):
            data = list(array)
            mutate(data)
            with self.assertRaises(ValueError):
                BitEvidence.from_bytes(
                    json.dumps(data, separators=(",", ":")).encode()
                )

    def test_rejects_non_array(self):
        with self.assertRaises(ValueError):
            BitEvidence.from_bytes(b"{}")

    def test_rejects_bad_hex_and_lengths(self):
        array = session(self._blob())
        # Uppercase hex.
        broken = list(array)
        broken[1] = broken[1].upper()
        with self.assertRaises(ValueError):
            BitEvidence.from_bytes(json.dumps(broken, separators=(",", ":")).encode())
        # t one byte short.
        broken = list(array)
        broken[1] = bytes.fromhex(broken[1])[:-1].hex()
        with self.assertRaises(ValueError):
            BitEvidence.from_bytes(json.dumps(broken, separators=(",", ":")).encode())
        # r one byte short.
        broken = list(array)
        broken[5][0][1] = bytes.fromhex(broken[5][0][1])[:-1].hex()
        with self.assertRaises(ValueError):
            BitEvidence.from_bytes(json.dumps(broken, separators=(",", ":")).encode())

    def test_rejects_bool_and_out_of_range_bits(self):
        array = session(self._blob())
        for bad_bit in (True, False, 2, -1):
            broken = list(array)
            broken[5][0][0] = bad_bit
            with self.assertRaises(ValueError):
                BitEvidence.from_bytes(
                    json.dumps(broken, separators=(",", ":")).encode()
                )

    def test_rejects_bad_query_shape(self):
        array = session(self._blob())
        broken = list(array)
        broken[5][0] = [0, broken[5][0][1], 1.0]
        with self.assertRaises(ValueError):
            BitEvidence.from_bytes(json.dumps(broken, separators=(",", ":")).encode())

    def test_rejects_non_finite_numbers(self):
        array = session(self._blob())
        for index in (6, 7, 8):
            for bad in ("1e999", "true"):
                broken = list(array)
                broken[index] = json.loads(bad)
                with self.assertRaises(ValueError):
                    BitEvidence.from_bytes(
                        json.dumps(broken, separators=(",", ":")).encode()
                    )
        for slot in (2, 3):
            broken = list(array)
            broken[5][0][slot] = math.inf
            with self.assertRaises(ValueError):
                BitEvidence.from_bytes(
                    json.dumps(broken, separators=(",", ":")).encode()
                )

    def test_rejects_non_positive_timeout_and_negative_limit(self):
        array = session(self._blob())
        for index, bad in ((7, 0.0), (7, -1.0), (8, -0.1)):
            broken = list(array)
            broken[index] = bad
            with self.assertRaises(ValueError):
                BitEvidence.from_bytes(
                    json.dumps(broken, separators=(",", ":")).encode()
                )

    def test_rejects_empty_queries(self):
        array = session(self._blob())
        broken = list(array)
        broken[5] = []
        with self.assertRaises(ValueError):
            BitEvidence.from_bytes(json.dumps(broken, separators=(",", ":")).encode())

    def test_rejects_integer_clock_literal_on_canonical_round_trip(self):
        # s/e are floats in the contract; an int literal re-encodes to a
        # different spelling, so canonical re-encoding must reject it.
        array = session(self._blob())
        broken = list(array)
        broken[5][0][2] = 1  # int literal instead of 1.0
        with self.assertRaises(ValueError):
            BitEvidence.from_bytes(json.dumps(broken, separators=(",", ":")).encode())

    def test_rejects_whitespace_and_pretty_printing(self):
        with self.assertRaises(ValueError):
            BitEvidence.from_bytes(json.dumps(session(self._blob()), indent=2).encode())


class AuditBTest(unittest.TestCase):
    def _blob(self, rounds=4, timeout=0.001, speed=299_792_458.0, clock=None):
        clock = clock or SteppedClock()
        return verifier(clock, speed).bits(
            RecordingProver(KEY, clock), CONTEXT, OPENING,
            rounds=rounds, timeout=timeout,
        )

    def test_returns_recomputed_limit(self):
        clock = SteppedClock(step=0.00003)
        blob = self._blob(clock=clock)
        self.assertEqual(audit_b(blob, KEY), 0.00003 * 299_792_458.0 / 2.0)

    def test_x_and_k_must_be_non_empty_bytes(self):
        blob = self._blob()
        record = BitEvidence.from_bytes(blob)
        for bad_x in (record, bytearray(blob), blob.decode(), b"", None, 42):
            with self.assertRaises(ValueError):
                audit_b(bad_x, KEY)
        for bad_k in (b"", bytearray(KEY), "k", None, 42):
            with self.assertRaises(ValueError):
                audit_b(blob, bad_k)

    def test_wrong_key_rejected(self):
        with self.assertRaises(ValueError):
            audit_b(self._blob(), OTHER_KEY)

    def test_tampered_blob_rejected(self):
        blob = self._blob()
        for flip in (1, 20, len(blob) // 2, len(blob) - 5):
            broken = bytearray(blob)
            broken[flip] ^= 0xFF
            with self.assertRaises((ValueError, json.JSONDecodeError)):
                audit_b(bytes(broken), KEY)

    def test_digest_recomputed_even_with_valid_mac(self):
        # Re-signed with the right key: MAC passes but D != H(NPFC1+C+O).
        def mutate(array):
            array[3] = hashlib.sha256(b"forged").digest().hex()

        with self.assertRaises(ValueError):
            audit_b(resign(self._blob(), mutate), KEY)

    def test_response_recomputed_by_index_even_with_valid_mac(self):
        def mutate(array):
            # Swap two whole queries: each r is now checked at a new index.
            array[5][0], array[5][1] = array[5][1], array[5][0]

        with self.assertRaises(ValueError):
            audit_b(resign(self._blob(), mutate), KEY)

    def test_forged_response_even_with_valid_mac(self):
        def mutate(array):
            array[5][0][1] = b"\x00" * 32 .hex()

        with self.assertRaises(ValueError):
            audit_b(resign(self._blob(), mutate), KEY)

    def test_round_trip_over_timeout_rejected_even_with_valid_mac(self):
        def mutate(array):
            array[5][0][3] = array[5][0][2] + array[7] + 1.0

        with self.assertRaises(ValueError):
            audit_b(resign(self._blob(), mutate), KEY)

    def test_negative_round_trip_rejected_even_with_valid_mac(self):
        def mutate(array):
            array[5][0][3] = array[5][0][2] - 0.0001

        with self.assertRaises(ValueError):
            audit_b(resign(self._blob(), mutate), KEY)

    def test_limit_recomputed_even_with_valid_mac(self):
        def mutate(array):
            array[8] = array[8] + 1.0

        with self.assertRaises(ValueError):
            audit_b(resign(self._blob(), mutate), KEY)

    def test_boundary_round_trip_equal_timeout_accepted(self):
        clock = SteppedClock(step=0.0001)
        blob = self._blob(rounds=2, timeout=0.0001, clock=clock)
        self.assertEqual(audit_b(blob, KEY), 0.0001 * 299_792_458.0 / 2.0)

    def test_zero_round_trip_accepted(self):
        clock = SteppedClock()

        class Instant:
            def __init__(self):
                self.p = Prover(KEY)

            def bit(self, t, d, i, b):
                return self.p.bit(t, d, i, b)

        blob = verifier(clock).bits(Instant(), CONTEXT, OPENING, rounds=3)
        self.assertEqual(audit_b(blob, KEY), 0.0)

    def test_uses_maximum_round_trip_for_limit(self):
        # Build a blob whose durations differ: L must track the largest.
        clock = SteppedClock(step=0.00001)
        prover = RecordingProver(KEY, clock)

        class VariableDelay:
            def __init__(self):
                self.real = prover
                self.n = 0

            def bit(self, t, d, i, b):
                self.n += 1
                clock.now = 1000.0 + 0.00001 * self.n
                if self.n == 2:
                    clock.now += 0.00004  # one slow round: 0.00005 total
                return self.real.bit(t, d, i, b)

        blob = verifier(clock).bits(
            VariableDelay(), CONTEXT, OPENING, rounds=3, timeout=0.001
        )
        self.assertEqual(audit_b(blob, KEY), 0.00005 * 299_792_458.0 / 2.0)


