    def test_d_contract(self):
        for bad in (b"", b"x" * 31, b"x" * 33, bytearray(32), "d" * 32, None):
            with self.assertRaises(ValueError):
                Prover(KEY).bit(b"t" * 16, bad, 0, 0)

